def GetProgram(system_id, name, include_source=None, language=None, abap_language_version=None, use_cache=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0303000" if __import__("os").path.isdir("./environment_mix/0303000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(19))

    tool_name = "GetProgram"

    # ---- validate inputs (RELAXED: accept real datastore ids even if schema pattern was wrong) ----
    if not isinstance(system_id, str) or not system_id:
        return _err("VALIDATION_ERROR", "system_id must be a non-empty string.")
    # Accept both 19 and 26 char suffixes (datastore uses longer ULID-like suffixes)
    if re.match(r"^adt_sys_[0-9A-Z]{19,32}$", system_id) is None:
        return _err("VALIDATION_ERROR", "Invalid system_id format.")
    if not isinstance(name, str) or len(name) < 1:
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if include_source is not None and not isinstance(include_source, bool):
        return _err("VALIDATION_ERROR", "include_source must be a boolean.")
    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.")
    if language is not None and (not isinstance(language, str) or len(language) < 1):
        return _err("VALIDATION_ERROR", "language must be a non-empty string.")
    if abap_language_version is not None and (not isinstance(abap_language_version, str) or len(abap_language_version) < 1):
        return _err("VALIDATION_ERROR", "abap_language_version must be a non-empty string.")

    include_source = bool(include_source) if include_source is not None else False
    use_cache = bool(use_cache) if use_cache is not None else False

    # ---- load store ----
    systems = _load("adt_systems.json")
    keys = _load("api_keys.json")
    objects = _load("abap_objects.json")
    artifacts = _load("abap_object_artifacts.json")
    requests = _load("tool_requests.json")

    sys_row = next((s for s in systems if isinstance(s, dict) and s.get("id") == system_id), None)
    if not sys_row or sys_row.get("status") != "active":
        return _err("NOT_FOUND", "ADT system not found or not active.")

    # ---- resolve an authenticated context that can actually serve this call ----
    def _key_reject_reason(k):
        if not isinstance(k, dict):
            return "BAD_KEY"
        if k.get("system_id") != system_id:
            return "SYSTEM_MISMATCH"
        st = k.get("status")
        if st == "revoked":
            return "KEY_REVOKED"
        if st == "expired":
            return "KEY_EXPIRED"
        if st != "active":
            return "KEY_REVOKED"
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now:
            return "KEY_EXPIRED"
        allowed = k.get("allowed_tools")
        if isinstance(allowed, list) and len(allowed) > 0 and tool_name not in allowed:
            return "NOT_ALLOWED"
        return None

    candidate = None
    any_reject = None
    for k in keys:
        reason = _key_reject_reason(k)
        if reason is None:
            candidate = k
            break
        if reason in ("KEY_REVOKED", "KEY_EXPIRED") and any_reject is None:
            any_reject = reason

    if candidate is None:
        # No usable combination anywhere for this system/tool
        if any_reject in ("KEY_REVOKED", "KEY_EXPIRED"):
            # Must record rejected request even without a usable key: pick a matching key row to anchor audit if possible
            anchor = next((k for k in keys if isinstance(k, dict) and k.get("system_id") == system_id and k.get("status") in ("revoked", "expired")), None)
            if anchor is None:
                return _err("UNAUTHORIZED", "No active API key available for this system.")
            req_id = _new_id("adt_req")
            req_row = {
                "id": req_id,
                "api_key_id": anchor.get("id"),
                "system_id": system_id,
                "tool_name": tool_name,
                "request_params": {"name": name, "include_source": include_source, "language": language, "abap_language_version": abap_language_version, "use_cache": use_cache},
                "resolved_object_id": None,
                "http_status": None,
                "duration_ms": max(0, int((time.time() - t0) * 1000)),
                "error_code": any_reject,
                "error_message": "API key is revoked" if any_reject == "KEY_REVOKED" else "API key has expired",
                "result_artifact_id": None,
                "status": "rejected",
                "requested_at": _iso(now),
                "completed_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            requests.append(req_row)
            _save("tool_requests.json", requests)
            return _err("UNAUTHORIZED", req_row["error_message"])
        return _err("UNAUTHORIZED", "No active API key available for this system.")

    api_key = candidate

    # ---- create tool_requests row with status=received BEFORE any upstream/caching work ----
    req_id = _new_id("adt_req")
    safe_params = {
        "name": name,
        "include_source": include_source,
        "language": language,
        "abap_language_version": abap_language_version,
        "use_cache": use_cache,
    }
    req_row = {
        "id": req_id,
        "api_key_id": api_key["id"],
        "system_id": system_id,
        "tool_name": tool_name,
        "request_params": safe_params,
        "resolved_object_id": None,
        "http_status": None,
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "result_artifact_id": None,
        "status": "received",
        "requested_at": _iso(now),
        "completed_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    requests.append(req_row)
    _save("tool_requests.json", requests)

    # ---- rate limit / quota enforcement (using tool_requests.requested_at) ----
    def _count_within(predicate):
        c = 0
        for r in requests:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key["id"]:
                continue
            dt = _parse_dt(r.get("requested_at"))
            if dt is None:
                continue
            if predicate(dt):
                c += 1
        return c

    per_min = api_key.get("requests_per_minute_limit")
    per_day = api_key.get("requests_per_day_limit")
    try:
        per_min = int(per_min)
    except Exception:
        per_min = 0
    try:
        per_day = int(per_day)
    except Exception:
        per_day = 0

    minute_window_start = now - datetime.timedelta(seconds=60)
    day_window_start = now - datetime.timedelta(days=1)

    # include current "received" request in counts
    min_count = _count_within(lambda dt: dt >= minute_window_start)
    day_count = _count_within(lambda dt: dt >= day_window_start)

    def _finish_rejected(error_code, message, api_error_code):
        # transition received -> rejected only (legal)
        req_row["status"] = "rejected"
        req_row["error_code"] = error_code
        req_row["error_message"] = message
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["completed_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_row["updated_at"] = req_row["completed_at"]
        api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        api_key["updated_at"] = api_key.get("updated_at") or _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("tool_requests.json", requests)
        _save("api_keys.json", keys)
        return _err(api_error_code, message)

    if api_key.get("system_id") != system_id:
        return _finish_rejected("SYSTEM_MISMATCH", "API key does not match requested system.", "UNAUTHORIZED")

    if per_min >= 0 and per_min != 0 and min_count > per_min:
        return _finish_rejected("RATE_LIMITED", "Rate limit exceeded (per-minute).", "RATE_LIMIT")
    if per_day >= 0 and per_day != 0 and day_count > per_day:
        return _finish_rejected("RATE_LIMITED", "Rate limit exceeded (per-day).", "QUOTA_EXCEEDED")

    # tool allowed_tools already checked in selection; still enforce
    allowed_tools = api_key.get("allowed_tools")
    if isinstance(allowed_tools, list) and len(allowed_tools) > 0 and tool_name not in allowed_tools:
        return _finish_rejected("NOT_ALLOWED", "Tool not allowed for this API key.", "UNAUTHORIZED")

    # ---- transition to running (must not skip) ----
    req_row["status"] = "running"
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("tool_requests.json", requests)

    # ---- use cache if allowed ----
    obj = next((o for o in objects if isinstance(o, dict) and o.get("system_id") == system_id and o.get("object_type") == "PROGRAM" and o.get("name") == name), None)
    source_art = None
    if obj and use_cache:
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("object_id") == obj.get("id") and a.get("artifact_kind") == "SOURCE" and a.get("status") == "current":
                source_art = a
                break

    # ---- "upstream" success simulation: if no cached artifact, still create/update rows (real backend would fetch) ----
    # Create/upsert object
    ts = _iso(datetime.datetime.now(datetime.timezone.utc))
    if obj is None:
        obj = {
            "id": _new_id("adt_obj"),
            "system_id": system_id,
            "object_type": "PROGRAM",
            "name": name,
            "package_name": None,
            "uri": f"/sap/bc/adt/programs/programs/{name}",
            "description": None,
            "is_standard": (not name.upper().startswith("Z") and not name.upper().startswith("Y")),
            "status": "known",
            "last_indexed_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        objects.append(obj)
    else:
        obj["status"] = "known" if obj.get("status") in ("known", "stale") else obj.get("status")
        obj["last_indexed_at"] = ts
        obj["updated_at"] = ts
        if not obj.get("uri"):
            obj["uri"] = f"/sap/bc/adt/programs/programs/{name}"

    # If include_source, ensure an artifact exists/current
    result_source = None
    result_art_id = None
    if include_source:
        if source_art is None:
            # supersede previous currents for same kind
            for a in artifacts:
                if isinstance(a, dict) and a.get("object_id") == obj["id"] and a.get("artifact_kind") == "SOURCE" and a.get("status") == "current":
                    a["status"] = "superseded"
                    a["updated_at"] = ts
            source_art = {
                "id": _new_id("adt_art"),
                "object_id": obj["id"],
                "artifact_kind": "SOURCE",
                "content_type": "text/plain; charset=utf-8",
                "payload_text": f"* Retrieved source for PROGRAM {name}\n* Language={language or sys_row.get('default_language')}\n* ABAP_LV={abap_language_version or sys_row.get('default_abap_language_version')}\n",
                "payload_json": None,
                "etag": None,
                "retrieved_at": ts,
                "retrieved_by_key_id": api_key["id"],
                "status": "current",
                "created_at": ts,
                "updated_at": ts,
            }
            artifacts.append(source_art)
        result_source = source_art.get("payload_text")
        result_art_id = source_art.get("id")

    # ---- finalize request succeeded ----
    req_row["status"] = "succeeded"
    req_row["resolved_object_id"] = obj["id"]
    req_row["result_artifact_id"] = result_art_id
    req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    req_row["completed_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    req_row["updated_at"] = req_row["completed_at"]
    api_key["last_used_at"] = req_row["completed_at"]
    api_key["updated_at"] = api_key.get("updated_at") or req_row["completed_at"]

    _save("abap_objects.json", objects)
    _save("abap_object_artifacts.json", artifacts)
    _save("tool_requests.json", requests)
    _save("api_keys.json", keys)

    return {
        "request_id": req_row["id"],
        "system_id": system_id,
        "object": obj,
        "source": result_source if include_source else None,
        "artifact_id": result_art_id,
    }

def GetClass(system_id, name, include_source=None, language=None, abap_language_version=None, use_cache=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0303000" if __import__("os").path.isdir("./environment_mix/0303000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(19))

    tool_name = "GetClass"

    if not isinstance(system_id, str) or not system_id:
        return _err("VALIDATION_ERROR", "system_id must be a non-empty string.")
    if re.match(r"^adt_sys_[0-9A-Z]{19,32}$", system_id) is None:
        return _err("VALIDATION_ERROR", "Invalid system_id format.")
    if not isinstance(name, str) or len(name) < 1:
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if include_source is not None and not isinstance(include_source, bool):
        return _err("VALIDATION_ERROR", "include_source must be a boolean.")
    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.")
    if language is not None and (not isinstance(language, str) or len(language) < 1):
        return _err("VALIDATION_ERROR", "language must be a non-empty string.")
    if abap_language_version is not None and (not isinstance(abap_language_version, str) or len(abap_language_version) < 1):
        return _err("VALIDATION_ERROR", "abap_language_version must be a non-empty string.")

    include_source = bool(include_source) if include_source is not None else False
    use_cache = bool(use_cache) if use_cache is not None else False

    systems = _load("adt_systems.json")
    keys = _load("api_keys.json")
    objects = _load("abap_objects.json")
    artifacts = _load("abap_object_artifacts.json")
    requests = _load("tool_requests.json")

    sys_row = next((s for s in systems if isinstance(s, dict) and s.get("id") == system_id), None)
    if not sys_row or sys_row.get("status") != "active":
        return _err("NOT_FOUND", "ADT system not found or not active.")

    def _key_reject_reason(k):
        if not isinstance(k, dict):
            return "BAD_KEY"
        if k.get("system_id") != system_id:
            return "SYSTEM_MISMATCH"
        st = k.get("status")
        if st == "revoked":
            return "KEY_REVOKED"
        if st == "expired":
            return "KEY_EXPIRED"
        if st != "active":
            return "KEY_REVOKED"
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now:
            return "KEY_EXPIRED"
        allowed = k.get("allowed_tools")
        if isinstance(allowed, list) and len(allowed) > 0 and tool_name not in allowed:
            return "NOT_ALLOWED"
        return None

    api_key = None
    any_reject = None
    for k in keys:
        reason = _key_reject_reason(k)
        if reason is None:
            api_key = k
            break
        if reason in ("KEY_REVOKED", "KEY_EXPIRED") and any_reject is None:
            any_reject = reason
    if api_key is None:
        if any_reject in ("KEY_REVOKED", "KEY_EXPIRED"):
            anchor = next((k for k in keys if isinstance(k, dict) and k.get("system_id") == system_id and k.get("status") in ("revoked", "expired")), None)
            if anchor is None:
                return _err("UNAUTHORIZED", "No active API key available for this system.")
            req_id = _new_id("adt_req")
            ts = _iso(now)
            requests.append({
                "id": req_id,
                "api_key_id": anchor.get("id"),
                "system_id": system_id,
                "tool_name": tool_name,
                "request_params": {"name": name, "include_source": include_source, "language": language, "abap_language_version": abap_language_version, "use_cache": use_cache},
                "resolved_object_id": None,
                "http_status": None,
                "duration_ms": max(0, int((time.time() - t0) * 1000)),
                "error_code": any_reject,
                "error_message": "API key is revoked" if any_reject == "KEY_REVOKED" else "API key has expired",
                "result_artifact_id": None,
                "status": "rejected",
                "requested_at": ts,
                "completed_at": ts,
                "created_at": ts,
                "updated_at": ts,
            })
            _save("tool_requests.json", requests)
            return _err("UNAUTHORIZED", "API key is revoked" if any_reject == "KEY_REVOKED" else "API key has expired")
        return _err("UNAUTHORIZED", "No active API key available for this system.")

    # received
    req_id = _new_id("adt_req")
    ts0 = _iso(now)
    req_row = {
        "id": req_id,
        "api_key_id": api_key["id"],
        "system_id": system_id,
        "tool_name": tool_name,
        "request_params": {"name": name, "include_source": include_source, "language": language, "abap_language_version": abap_language_version, "use_cache": use_cache},
        "resolved_object_id": None,
        "http_status": None,
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "result_artifact_id": None,
        "status": "received",
        "requested_at": ts0,
        "completed_at": None,
        "created_at": ts0,
        "updated_at": ts0,
    }
    requests.append(req_row)
    _save("tool_requests.json", requests)

    def _count_within(predicate):
        c = 0
        for r in requests:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key["id"]:
                continue
            dt = _parse_dt(r.get("requested_at"))
            if dt is None:
                continue
            if predicate(dt):
                c += 1
        return c

    try:
        per_min = int(api_key.get("requests_per_minute_limit"))
    except Exception:
        per_min = 0
    try:
        per_day = int(api_key.get("requests_per_day_limit"))
    except Exception:
        per_day = 0

    def _finish_rejected(error_code, message, api_error_code):
        req_row["status"] = "rejected"
        req_row["error_code"] = error_code
        req_row["error_message"] = message
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        done = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_row["completed_at"] = done
        req_row["updated_at"] = done
        api_key["last_used_at"] = done
        api_key["updated_at"] = api_key.get("updated_at") or done
        _save("tool_requests.json", requests)
        _save("api_keys.json", keys)
        return _err(api_error_code, message)

    if api_key.get("system_id") != system_id:
        return _finish_rejected("SYSTEM_MISMATCH", "API key does not match requested system.", "UNAUTHORIZED")

    min_count = _count_within(lambda dt: dt >= (now - datetime.timedelta(seconds=60)))
    day_count = _count_within(lambda dt: dt >= (now - datetime.timedelta(days=1)))

    if per_min >= 0 and per_min != 0 and min_count > per_min:
        return _finish_rejected("RATE_LIMITED", "Rate limit exceeded (per-minute).", "RATE_LIMIT")
    if per_day >= 0 and per_day != 0 and day_count > per_day:
        return _finish_rejected("RATE_LIMITED", "Rate limit exceeded (per-day).", "QUOTA_EXCEEDED")

    # running
    req_row["status"] = "running"
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("tool_requests.json", requests)

    obj = next((o for o in objects if isinstance(o, dict) and o.get("system_id") == system_id and o.get("object_type") == "CLASS" and o.get("name") == name), None)
    source_art = None
    if obj and use_cache:
        source_art = next((a for a in artifacts if isinstance(a, dict) and a.get("object_id") == obj.get("id") and a.get("artifact_kind") == "SOURCE" and a.get("status") == "current"), None)

    ts = _iso(datetime.datetime.now(datetime.timezone.utc))
    if obj is None:
        obj = {
            "id": _new_id("adt_obj"),
            "system_id": system_id,
            "object_type": "CLASS",
            "name": name,
            "package_name": None,
            "uri": f"/sap/bc/adt/oo/classes/{name}",
            "description": None,
            "is_standard": (not name.upper().startswith("Z") and not name.upper().startswith("Y")),
            "status": "known",
            "last_indexed_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        objects.append(obj)
    else:
        obj["status"] = "known" if obj.get("status") in ("known", "stale") else obj.get("status")
        obj["last_indexed_at"] = ts
        obj["updated_at"] = ts
        if not obj.get("uri"):
            obj["uri"] = f"/sap/bc/adt/oo/classes/{name}"

    result_source = None
    result_art_id = None
    if include_source:
        if source_art is None:
            for a in artifacts:
                if isinstance(a, dict) and a.get("object_id") == obj["id"] and a.get("artifact_kind") == "SOURCE" and a.get("status") == "current":
                    a["status"] = "superseded"
