            return "KEY_REVOKED"
        if st == "expired":
            return "KEY_EXPIRED"
        if st != "active":
            return "KEY_REVOKED"
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now:
            return "KEY_EXPIRED"
        allowed = k.get("allowed_tools")
