                "retrieved_at": ts,
                "retrieved_by_key_id": api_key["id"],
                "status": "current",
                "created_at": ts,
                "updated_at": ts,
            }
            artifacts.append(schema_art)
        result_schema = schema_art.get("payload_json")
        result_art_id = schema_art.get("id")

    req_row["status"] = "succeeded"
    req_row["resolved_object_id"] = obj["id"]
    req_row["result_artifact_id"] = result_art_id
    req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
