                    "language": language or sys_row.get("default_language"),
                    "fields": [],
                    "keys": []
                },
                "etag": None,
                "retrieved_at": ts,
                "retrieved_by_key_id": api_key["id"],
                "status": "current",
                "created_at": ts,
                "updated_at": ts,
            }
            artifacts.append(schema_art)
        result_schema = schema_art.get("payload_json")
        result_art_id = schema_art.get("id")

    req_row["status"] = "succeeded"
    req_row["resolved_object_id"] = obj["id"]
    req_row["result_artifact_id"] = result_art_id
    req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    done = _iso(datetime.datetime.now(datetime.timezone.utc))
    req_row["completed_at"] = done
    req_row["updated_at"] = done
    api_key["last_used_at"] = done
    api_key["updated_at"] = api_key.get("updated_at") or done

    _save("abap_objects.json", objects)
    _save("abap_object_artifacts.json", artifacts)
    _save("tool_requests.json", requests)
    _save("api_keys.json", keys)

    return {"request_id": req_row["id"], "system_id": system_id, "object": obj, "schema": result_schema if include_schema else None, "artifact_id": result_art_id}

def GetTableContents(system_id, name, fields=None, where=None, order_by=None, limit=None, offset=None, use_cache=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0303000" if __import__("os").path.isdir("./environment_mix/0303000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(19))

    def _safe_params():
        # Only log non-sensitive parameters.
        out = {"system_id": system_id, "name": name}
        if fields is not None:
            out["fields"] = fields
        if where is not None:
            out["where"] = where
        if order_by is not None:
            out["order_by"] = order_by
        if limit is not None:
            out["limit"] = limit
        if offset is not None:
            out["offset"] = offset
        if use_cache is not None:
            out["use_cache"] = use_cache
        return out

    tool_name = "GetTableContents"

    # -------- Validate inputs (relax overly strict "expression" validation: accept strings) --------
    if not isinstance(system_id, str) or not system_id.strip():
        return _err("VALIDATION_ERROR", "system_id must be a non-empty string.")
    system_id = system_id.strip()
    # Accept store's ids (adt_sys_...) and vendor ids (if any); store uses 19 chars but be lenient
    if re.match(r"^adt_sys_[0-9A-Z]{19,32}$", system_id) is None:
        return _err("VALIDATION_ERROR", "system_id format is invalid.")

    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    name = name.strip()

    if fields is not None:
        if not isinstance(fields, list):
            return _err("VALIDATION_ERROR", "fields must be an array of strings when provided.")
        for i, f in enumerate(fields):
            if not isinstance(f, str) or not f.strip():
                return _err("VALIDATION_ERROR", f"fields[{i}] must be a non-empty string.")

    if where is not None:
        if not isinstance(where, str) or not where.strip():
            return _err("VALIDATION_ERROR", "where must be a non-empty string when provided.")
        where = where.strip()

    if order_by is not None:
        if not isinstance(order_by, str) or not order_by.strip():
            return _err("VALIDATION_ERROR", "order_by must be a non-empty string when provided.")
        order_by = order_by.strip()

    if limit is not None:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1:
            return _err("VALIDATION_ERROR", "limit must be an integer >= 1 when provided.")

    if offset is not None:
        if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
            return _err("VALIDATION_ERROR", "offset must be an integer >= 0 when provided.")

    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean when provided.")

    # -------- Load datastore --------
    systems = _load("adt_systems.json")
    keys = _load("api_keys.json")
    objects = _load("abap_objects.json")
    artifacts = _load("abap_object_artifacts.json")
    requests = _load("tool_requests.json")

    if not isinstance(systems, list):
        systems = []
    if not isinstance(keys, list):
        keys = []
    if not isinstance(objects, list):
        objects = []
    if not isinstance(artifacts, list):
        artifacts = []
    if not isinstance(requests, list):
        requests = []

    # Resolve system
    system = next((s for s in systems if isinstance(s, dict) and s.get("id") == system_id), None)
    if system is None:
        return _err("NOT_FOUND", "ADT system not found.")

    # -------- Ambient authentication resolution --------
    # No explicit credential param exists in this tool; choose an api_key that can serve this request.
    # Must satisfy: system match, active, not expired, tool allowed, table reads enabled on both.
    def _key_is_valid(k):
        if not isinstance(k, dict):
            return False
        if k.get("system_id") != system_id:
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now:
            return False
        allowed = k.get("allowed_tools")
        if isinstance(allowed, list) and len(allowed) > 0 and tool_name not in allowed:
            return False
        # Enforce table read enablement
        if not system.get("allow_table_reads", False):
            return False
        if not k.get("allow_table_reads", False):
            return False
        return True

    chosen_key = next((k for k in keys if _key_is_valid(k)), None)

    # If no fully-valid key exists, we still must record a rejected request if there exists
    # any key for the system; choose a "best candidate" to attach the audit row to.
    fallback_key = next((k for k in keys if isinstance(k, dict) and k.get("system_id") == system_id), None)

    api_key = chosen_key or fallback_key
    if api_key is None:
        # No usable authentication context at all in store.
        # No request row can be created due to missing api_key_id FK.
        return _err("UNAUTHORIZED", "No authenticated API key context available for this request.")

    api_key_id = api_key.get("id")
    if not isinstance(api_key_id, str) or not api_key_id:
        return _err("UNAUTHORIZED", "No authenticated API key context available for this request.")

    # -------- Create tool_requests row with status=received BEFORE enforcement/execution --------
    req_id = _new_id("adt_req")
    requested_at = _iso(now)
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "system_id": system_id,
        "tool_name": tool_name,
        "request_params": _safe_params(),
        "resolved_object_id": None,
        "http_status": None,
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "result_artifact_id": None,
        "status": "received",
        "requested_at": requested_at,
        "completed_at": None,
        "created_at": requested_at,
        "updated_at": requested_at,
    }
    requests.append(req_row)
    _save("tool_requests.json", requests)

    def _finalize(status, error_code=None, error_message=None, http_status=None, resolved_object_id=None, result_artifact_id=None):
        # lifecycle: received -> running|rejected|failed, running -> succeeded|failed
        nonlocal req_row, requests
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        if http_status is not None:
            req_row["http_status"] = http_status
        if resolved_object_id is not None:
            req_row["resolved_object_id"] = resolved_object_id
        if result_artifact_id is not None:
            req_row["result_artifact_id"] = result_artifact_id
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["status"] = status
        if status in ("succeeded", "failed", "rejected"):
            req_row["completed_at"] = req_row["updated_at"]
        # persist (update in list by id)
        for i, r in enumerate(requests):
            if isinstance(r, dict) and r.get("id") == req_row["id"]:
                requests[i] = req_row
                break
        _save("tool_requests.json", requests)

    # -------- Reject conditions (key/system policy), rate limits, etc. --------
    # system mismatch rule (must equal api_keys.system_id) - already ensured for chosen_key;
    # if we only had fallback key from another system we'd reject as SYSTEM_MISMATCH.
    if api_key.get("system_id") != system_id:
        _finalize("rejected", error_code="SYSTEM_MISMATCH", error_message="Tool request system does not match API key system.")
        return _err("UNAUTHORIZED", "System mismatch for API key.")

    # key status / expiry
    if api_key.get("status") != "active":
        code = "KEY_REVOKED" if api_key.get("status") == "revoked" else "KEY_EXPIRED"
        msg = "API key is revoked" if code == "KEY_REVOKED" else "API key has expired"
        _finalize("rejected", error_code=code, error_message=msg)
        return _err("UNAUTHORIZED", msg)

    exp = _parse_dt(api_key.get("expires_at"))
    if exp is not None and exp <= now:
        _finalize("rejected", error_code="KEY_EXPIRED", error_message="API key has expired")
        return _err("UNAUTHORIZED", "API key has expired")

    # enforce tool allowlist
    allowed = api_key.get("allowed_tools")
    if isinstance(allowed, list) and len(allowed) > 0 and tool_name not in allowed:
        _finalize("rejected", error_code="UNAUTHORIZED_TOOL", error_message="This API key is not allowed to call this tool.")
        return _err("UNAUTHORIZED", "This API key is not allowed to call this tool.")

    # table reads policy (this was previously causing false UNAUTHORIZED; ensure we use real boolean fields)
    if not bool(system.get("allow_table_reads")) or not bool(api_key.get("allow_table_reads")):
        _finalize("rejected", error_code="TABLE_READS_DISABLED", error_message="Table reads are disabled for this key or system.")
        return _err("UNAUTHORIZED", "Table reads are disabled for this key or system.")

    # rate limit & daily quota (based on tool_requests)
    per_min = api_key.get("requests_per_minute_limit")
    per_day = api_key.get("requests_per_day_limit")
    if not isinstance(per_min, int) or isinstance(per_min, bool) or per_min < 0:
        per_min = 0
    if not isinstance(per_day, int) or isinstance(per_day, bool) or per_day < 0:
        per_day = 0

    # Count requests for this key in the last 60 seconds and today.
    # Note: include the just-created "received" row in counts (conservative).
    def _same_day(a, b):
        return a.date() == b.date()

    last_60s = 0
    today = 0
    for r in requests:
        if not isinstance(r, dict) or r.get("api_key_id") != api_key_id:
            continue
        ra = _parse_dt(r.get("requested_at"))
        if ra is None:
            continue
        if _same_day(ra.astimezone(datetime.timezone.utc), now):
            today += 1
        if (now - ra).total_seconds() <= 60:
            last_60s += 1

    if per_min > 0 and last_60s > per_min:
        _finalize("rejected", error_code="RATE_LIMITED", error_message="Rate limit exceeded (per-minute)")
        return _err("RATE_LIMIT", "Rate limit exceeded.")
    if per_day > 0 and today > per_day:
        _finalize("rejected", error_code="RATE_LIMITED", error_message="Rate limit exceeded (per-day)")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")

    # -------- Transition received -> running --------
    _finalize("running", error_code=None, error_message=None)

    # Touch key last_used_at
    for i, k in enumerate(keys):
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k2 = dict(k)
            k2["last_used_at"] = _iso(now)
            k2["updated_at"] = _iso(now)
            keys[i] = k2
            api_key = k2
            _save("api_keys.json", keys)
            break

    # -------- "Upstream ADT" simulation using datastore cache only --------
    # For this offline server, we return cached TABLE_CONTENTS if use_cache and current exists.
    # Otherwise, treat as upstream unavailable (cannot actually call ADT).
    table_upper = name.upper()

    # Upsert abap_objects row (DDIC_TABLE)
    obj = next(
        (o for o in objects if isinstance(o, dict) and o.get("system_id") == system_id and o.get("object_type") == "DDIC_TABLE" and o.get("name") == table_upper),
        None,
    )
    if obj is None:
        obj_id = _new_id("adt_obj")
        obj = {
            "id": obj_id,
            "system_id": system_id,
            "object_type": "DDIC_TABLE",
            "name": table_upper,
            "package_name": None,
            "uri": None,
            "description": None,
            "is_standard": False if table_upper.startswith("Z") or table_upper.startswith("Y") else True,
            "status": "known",
            "last_indexed_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        objects.append(obj)
        _save("abap_objects.json", objects)
    else:
        # refresh metadata
        obj = dict(obj)
        obj["status"] = "known" if obj.get("status") in ("known", "stale") else obj.get("status")
        obj["last_indexed_at"] = _iso(now)
        obj["updated_at"] = _iso(now)
        for i, o in enumerate(objects):
            if isinstance(o, dict) and o.get("id") == obj["id"]:
                objects[i] = obj
                break
        _save("abap_objects.json", objects)

    object_id = obj.get("id")

    # Cache hit
    if use_cache is True:
        current = None
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("object_id") == object_id and a.get("artifact_kind") == "TABLE_CONTENTS" and a.get("status") == "current":
                current = a
                break
        if current is not None and isinstance(current.get("payload_json"), dict):
            payload = current["payload_json"]
            rows = payload.get("rows")
            if not isinstance(rows, list):
                rows = []
            # Enforce system row limit on returned rows (even from cache)
            row_cap = system.get("table_read_row_limit")
            if not isinstance(row_cap, int) or isinstance(row_cap, bool) or row_cap < 0:
                row_cap = 0
            if row_cap > 0:
                rows = rows[:row_cap]
            payload2 = dict(payload)
            payload2["rows"] = rows

            _finalize("succeeded", resolved_object_id=object_id, result_artifact_id=current.get("id"))
            return {
                "tool_request_id": req_id,
                "system_id": system_id,
                "object_id": object_id,
                "artifact_id": current.get("id"),
                "cached": True,
                "table": table_upper,
                "data": payload2,
            }

    # No cache / cache miss -> upstream not available offline => fail (no artifact written)
    _finalize("failed", error_code="ADT_UPSTREAM_UNAVAILABLE", error_message="ADT returned 503 Service Unavailable", http_status=503, resolved_object_id=object_id)
    return _err("CONFLICT", "Upstream ADT is unavailable in offline mode.", tool_request_id=req_id, http_status=503)

def GetPackage(system_id, name, include_details=None, language=None, use_cache=None, **_extra):
    import json, os, datetime, time, re, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0303000" if __import__("os").path.isdir("./environment_mix/0303000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(19))

    tool_name = "GetPackage"

    if not isinstance(system_id, str) or not system_id:
        return _err("VALIDATION_ERROR", "system_id must be a non-empty string.")
    if re.match(r"^adt_sys_[0-9A-Z]{19,32}$", system_id) is None:
        return _err("VALIDATION_ERROR", "Invalid system_id format.")
    if not isinstance(name, str) or len(name) < 1:
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if include_details is not None and not isinstance(include_details, bool):
        return _err("VALIDATION_ERROR", "include_details must be a boolean.")
    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.")
    if language is not None and (not isinstance(language, str) or len(language) < 1):
        return _err("VALIDATION_ERROR", "language must be a non-empty string.")

    include_details = bool(include_details) if include_details is not None else False
    use_cache = bool(use_cache) if use_cache is not None else False

    systems = _load("adt_systems.json")
    keys = _load("api_keys.json")
    objects = _load("abap_objects.json")
    artifacts = _load("abap_object_artifacts.json")
    requests = _load("tool_requests.json")

    sys_row = next((s for s in systems if isinstance(s, dict) and s.get("id") == system_id), None)
    if not sys_row or sys_row.get("status") != "active":
        return _err("NOT_FOUND", "ADT system not found or not active.")

    def _key_reject_reason(k):
        if not isinstance(k, dict):
            return "BAD_KEY"
        if k.get("system_id") != system_id:
            return "SYSTEM_MISMATCH"
        st = k.get("status")
        if st == "revoked":
            return "KEY_REVOKED"
        if st == "expired":
            return "KEY_EXPIRED"
        if st != "active":
            return "KEY_REVOKED"
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now:
            return "KEY_EXPIRED"
        allowed = k.get("allowed_tools")
        if isinstance(allowed, list) and len(allowed) > 0 and tool_name not in allowed:
            return "NOT_ALLOWED"
        return None

    api_key = None
    any_reject = None
    for k in keys:
        reason = _key_reject_reason(k)
        if reason is None:
            api_key = k
            break
        if reason in ("KEY_REVOKED", "KEY_EXPIRED") and any_reject is None:
            any_reject = reason
    if api_key is None:
        if any_reject in ("KEY_REVOKED", "KEY_EXPIRED"):
            anchor = next((k for k in keys if isinstance(k, dict) and k.get("system_id") == system_id and k.get("status") in ("revoked", "expired")), None)
            if anchor is None:
                return _err("UNAUTHORIZED", "No active API key available for this system.")
            req_id = _new_id("adt_req")
            ts = _iso(now)
            requests.append({
                "id": req_id,
                "api_key_id": anchor.get("id"),
                "system_id": system_id,
                "tool_name": tool_name,
                "request_params": {"name": name, "include_details": include_details, "language": language, "use_cache": use_cache},
                "resolved_object_id": None,
                "http_status": None,
                "duration_ms": max(0, int((time.time() - t0) * 1000)),
                "error_code": any_reject,
                "error_message": "API key is revoked" if any_reject == "KEY_REVOKED" else "API key has expired",
                "result_artifact_id": None,
                "status": "rejected",
                "requested_at": ts,
                "completed_at": ts,
                "created_at": ts,
                "updated_at": ts,
            })
            _save("tool_requests.json", requests)
            return _err("UNAUTHORIZED", "API key is revoked" if any_reject == "KEY_REVOKED" else "API key has expired")
        return _err("UNAUTHORIZED", "No active API key available for this system.")

    req_id = _new_id("adt_req")
    ts0 = _iso(now)
    req_row = {
        "id": req_id,
        "api_key_id": api_key["id"],
        "system_id": system_id,
        "tool_name": tool_name,
        "request_params": {"name": name, "include_details": include_details, "language": language, "use_cache": use_cache},
        "resolved_object_id": None,
        "http_status": None,
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "result_artifact_id": None,
        "status": "received",
        "requested_at": ts0,
        "completed_at": None,
        "created_at": ts0,
        "updated_at": ts0,
    }
    requests.append(req_row)
    _save("tool_requests.json", requests)

    def _count_within(predicate):
        c = 0
        for r in requests:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key["id"]:
                continue
            dt = _parse_dt(r.get("requested_at"))
            if dt is None:
                continue
            if predicate(dt):
                c += 1
        return c

    try:
        per_min = int(api_key.get("requests_per_minute_limit"))
    except Exception:
        per_min = 0
    try:
        per_day = int(api_key.get("requests_per_day_limit"))
    except Exception:
        per_day = 0

    def _finish_rejected(error_code, message, api_error_code):
        req_row["status"] = "rejected"
        req_row["error_code"] = error_code
        req_row["error_message"] = message
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        done = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_row["completed_at"] = done
        req_row["updated_at"] = done
        api_key["last_used_at"] = done
        api_key["updated_at"] = api_key.get("updated_at") or done
        _save("tool_requests.json", requests)
        _save("api_keys.json", keys)
        return _err(api_error_code, message)

    if api_key.get("system_id") != system_id:
        return _finish_rejected("SYSTEM_MISMATCH", "API key does not match requested system.", "UNAUTHORIZED")

    min_count = _count_within(lambda dt: dt >= (now - datetime.timedelta(seconds=60)))
    day_count = _count_within(lambda dt: dt >= (now - datetime.timedelta(days=1)))
    if per_min >= 0 and per_min != 0 and min_count > per_min:
        return _finish_rejected("RATE_LIMITED", "Rate limit exceeded (per-minute).", "RATE_LIMIT")
    if per_day >= 0 and per_day != 0 and day_count > per_day:
        return _finish_rejected("RATE_LIMITED", "Rate limit exceeded (per-day).", "QUOTA_EXCEEDED")

    req_row["status"] = "running"
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("tool_requests.json", requests)

    obj = next((o for o in objects if isinstance(o, dict) and o.get("system_id") == system_id and o.get("object_type") == "PACKAGE" and o.get("name") == name), None)
    details_art = None
    if obj and use_cache:
        details_art = next((a for a in artifacts if isinstance(a, dict) and a.get("object_id") == obj.get("id") and a.get("artifact_kind") == "PACKAGE_DETAILS" and a.get("status") == "current"), None)

    ts = _iso(datetime.datetime.now(datetime.timezone.utc))
    if obj is None:
        obj = {
            "id": _new_id("adt_obj"),
            "system_id": system_id,
            "object_type": "PACKAGE",
            "name": name,
            "package_name": None,
            "uri": f"/sap/bc/adt/packages/{name}",
            "description": None,
            "is_standard": (not name.upper().startswith("Z") and not name.upper().startswith("Y")),
            "status": "known",
            "last_indexed_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        objects.append(obj)
    else:
        obj["status"] = "known" if obj.get("status") in ("known", "stale") else obj.get("status")
        obj["last_indexed_at"] = ts
        obj["updated_at"] = ts
        if not obj.get("uri"):
            obj["uri"] = f"/sap/bc/adt/packages/{name}"

    result_details = None
    result_art_id = None
    if include_details:
        if details_art is None:
            for a in artifacts:
                if isinstance(a, dict) and a.get("object_id") == obj["id"] and a.get("artifact_kind") == "PACKAGE_DETAILS" and a.get("status") == "current":
                    a["status"] = "superseded"
                    a["updated_at"] = ts
            details_art = {
                "id": _new_id("adt_art"),
                "object_id": obj["id"],
                "artifact_kind": "PACKAGE_DETAILS",
                "content_type": "application/json",
                "payload_text": None,
                "payload_json": {
                    "name": name,
                    "language": language or sys_row.get("default_language"),
                    "description": None,
                    "attributes": {}
                },
                "etag": None,
                "retrieved_at": ts,
                "retrieved_by_key_id": api_key["id"],
                "status": "current",
                "created_at": ts,
                "updated_at": ts,
            }
            artifacts.append(details_art)
        result_details = details_art.get("payload_json")
        result_art_id = details_art.get("id")

    req_row["status"] = "succeeded"
    req_row["resolved_object_id"] = obj["id"]
    req_row["result_artifact_id"] = result_art_id
    req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    done = _iso(datetime.datetime.now(datetime.timezone.utc))
    req_row["completed_at"] = done
    req_row["updated_at"] = done
    api_key["last_used_at"] = done
    api_key["updated_at"] = api_key.get("updated_at") or done

    _save("abap_objects.json", objects)
    _save("abap_object_artifacts.json", artifacts)
    _save("tool_requests.json", requests)
    _save("api_keys.json", keys)

    return {"request_id": req_row["id"], "system_id": system_id, "object": obj, "details": result_details if include_details else None, "artifact_id": result_art_id}

def SearchObject(system_id, query, object_types=None, package_name=None, is_standard=None, language=None, limit=None, cursor=None, sort=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0303000" if __import__("os").path.isdir("./environment_mix/0303000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    if not isinstance(system_id, str) or not re.match(r"^adt_sys_[0-9A-Z]{18,}$", system_id or ""):
        return _err("VALIDATION_ERROR", "Invalid system_id.")
    if not isinstance(query, str) or len(query) < 1:
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if object_types is not None:
        if not isinstance(object_types, list):
            return _err("VALIDATION_ERROR", "object_types must be an array when provided.")
        allowed_ot = {"PROGRAM","CLASS","INTERFACE","FUNCTION_GROUP","FUNCTION_MODULE","INCLUDE","PACKAGE","DDIC_TABLE","DDIC_STRUCTURE","TYPEINFO"}
        for ot in object_types:
            if ot not in allowed_ot:
                return _err("VALIDATION_ERROR", "Invalid object_types entry.", value=ot)
    if package_name is not None and (not isinstance(package_name, str) or len(package_name) < 1):
        return _err("VALIDATION_ERROR", "package_name must be a non-empty string when provided.")
    if is_standard is not None and not isinstance(is_standard, bool):
        return _err("VALIDATION_ERROR", "is_standard must be boolean when provided.")
    if language is not None and (not isinstance(language, str) or len(language) < 1):
        return _err("VALIDATION_ERROR", "language must be a non-empty string when provided.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200 when provided.")
    if cursor is not None and (not isinstance(cursor, str) or len(cursor) < 1):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
    if sort is not None and sort not in ("name", "object_type", "package_name", "updated_at"):
        return _err("VALIDATION_ERROR", "Invalid sort field.")
    if sort_order is not None and sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid sort_order.")

    systems = _load("adt_systems.json")
    keys = _load("api_keys.json")
    objs = _load("abap_objects.json")
    reqs = _load("tool_requests.json")

    sys_row = next((s for s in systems if s.get("id") == system_id and s.get("status") == "active"), None)
    if not sys_row:
        return _err("NOT_FOUND", "ADT system not found or not active.", system_id=system_id)

    if not sys_row.get("allow_quick_search", False):
        # Need a key to record request; resolve any key for system to record rejection.
        # If none, UNAUTHORIZED.
        def _parse_dt(x):
            if not x:
                return None
            try:
                if isinstance(x, str) and x.endswith("Z"):
                    x = x[:-1]
                return datetime.datetime.fromisoformat(x)
            except Exception:
                return None
        eligible_keys = []
        for k in keys:
            if k.get("system_id") != system_id:
                continue
            if k.get("status") != "active":
                continue
            exp = _parse_dt(k.get("expires_at"))
            if exp is not None and not (exp > now):
                continue
            allowed = k.get("allowed_tools")
            if isinstance(allowed, list) and len(allowed) > 0 and "SearchObject" not in allowed:
                continue
            eligible_keys.append(k)
        if not eligible_keys:
            return _err("UNAUTHORIZED", "No active API key available for this system/tool.")
        api_key = sorted(eligible_keys, key=lambda r: (r.get("last_used_at") is None, r.get("updated_at") or ""))[0]

        req_id = "req_" + uuid.uuid4().hex
        req_row = {
            "id": req_id,
            "api_key_id": api_key["id"],
            "system_id": system_id,
            "tool_name": "SearchObject",
            "request_params": {
                "query": query,
                **({"object_types": object_types} if object_types is not None else {}),
                **({"package_name": package_name} if package_name is not None else {}),
                **({"is_standard": is_standard} if is_standard is not None else {}),
                **({"language": language} if language is not None else {}),
                **({"limit": limit} if limit is not None else {}),
                **({"cursor": cursor} if cursor is not None else {}),
                **({"sort": sort} if sort is not None else {}),
                **({"sort_order": sort_order} if sort_order is not None else {}),
            },
            "resolved_object_id": None,
            "http_status": None,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "error_code": "SEARCH_DISABLED",
            "error_message": "Search is disabled on this ADT system.",
            "result_artifact_id": None,
            "status": "rejected",
            "requested_at": now_iso,
            "completed_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        reqs.append(req_row)
        api_key["last_used_at"] = now_iso
        api_key["updated_at"] = now_iso
        _save("api_keys.json", keys)
        _save("tool_requests.json", reqs)
        return _err("UNAUTHORIZED", "Search disabled on this system.", request_id=req_id)

    def _parse_dt(x):
        if not x:
            return None
        try:
            if isinstance(x, str) and x.endswith("Z"):
                x = x[:-1]
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None

    eligible_keys = []
    for k in keys:
        if k.get("system_id") != system_id:
            continue
        if k.get("status") != "active":
            continue
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and not (exp > now):
            continue
        allowed = k.get("allowed_tools")
        if isinstance(allowed, list) and len(allowed) > 0 and "SearchObject" not in allowed:
            continue
        eligible_keys.append(k)
    if not eligible_keys:
        return _err("UNAUTHORIZED", "No active API key available for this system/tool.")
    api_key = sorted(eligible_keys, key=lambda r: (r.get("last_used_at") is None, r.get("updated_at") or ""))[0]

    req_id = "req_" + uuid.uuid4().hex
    safe_params = {
        "query": query,
        **({"object_types": object_types} if object_types is not None else {}),
        **({"package_name": package_name} if package_name is not None else {}),
        **({"is_standard": is_standard} if is_standard is not None else {}),
        **({"language": language} if language is not None else {}),
        **({"limit": limit} if limit is not None else {}),
        **({"cursor": cursor} if cursor is not None else {}),
        **({"sort": sort} if sort is not None else {}),
        **({"sort_order": sort_order} if sort_order is not None else {}),
    }
    req_row = {
        "id": req_id,
        "api_key_id": api_key["id"],
        "system_id": system_id,
        "tool_name": "SearchObject",
        "request_params": safe_params,
        "resolved_object_id": None,
        "http_status": None,
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "result_artifact_id": None,
        "status": "received",
        "requested_at": now_iso,
        "completed_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    reqs.append(req_row)
    _save("tool_requests.json", reqs)

    exp = _parse_dt(api_key.get("expires_at"))
    if api_key.get("status") != "active":
        req_row["status"] = "rejected"
        req_row["error_code"] = "KEY_REVOKED"
        req_row["error_message"] = "API key is not active."
        req_row["completed_at"] = now_iso
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        api_key["last_used_at"] = now_iso
        api_key["updated_at"] = now_iso
        _save("api_keys.json", keys)
        _save("tool_requests.json", reqs)
        return _err("UNAUTHORIZED", "API key revoked.", request_id=req_id)
    if exp is not None and not (exp > now):
        req_row["status"] = "rejected"
        req_row["error_code"] = "KEY_EXPIRED"
        req_row["error_message"] = "API key is expired."
        req_row["completed_at"] = now_iso
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        api_key["last_used_at"] = now_iso
        api_key["updated_at"] = now_iso
        _save("api_keys.json", keys)
        _save("tool_requests.json", reqs)
        return _err("UNAUTHORIZED", "API key expired.", request_id=req_id)

    if api_key.get("system_id") != system_id:
        req_row["status"] = "rejected"
        req_row["error_code"] = "SYSTEM_MISMATCH"
        req_row["error_message"] = "API key is not permitted for the requested system."
        req_row["completed_at"] = now_iso
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        api_key["last_used_at"] = now_iso
        api_key["updated_at"] = now_iso
        _save("api_keys.json", keys)
        _save("tool_requests.json", reqs)
        return _err("UNAUTHORIZED", "System mismatch.", request_id=req_id)

    rpm = api_key.get("requests_per_minute_limit")
    rpd = api_key.get("requests_per_day_limit")
    if not isinstance(rpm, int) or rpm < 0 or not isinstance(rpd, int) or rpd < 0:
        req_row["status"] = "failed"
        req_row["error_code"] = "VALIDATION_ERROR"
        req_row["error_message"] = "Server key limits misconfigured."
        req_row["completed_at"] = now_iso
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        api_key["last_used_at"] = now_iso
        api_key["updated_at"] = now_iso
        _save("api_keys.json", keys)
        _save("tool_requests.json", reqs)
        return _err("VALIDATION_ERROR", "Key limits misconfigured.", request_id=req_id)

    window_start = now - datetime.timedelta(seconds=60)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    recent = 0
    daily = 0
    for r in reqs:
        if r.get("api_key_id") != api_key["id"]:
            continue
        rd = _parse_dt(r.get("requested_at"))
        if rd is None:
            continue
        if rd >= window_start:
            recent += 1
        if rd >= day_start:
            daily += 1
    if (rpm >= 0 and recent > rpm) or (rpd >= 0 and daily > rpd):
        req_row["status"] = "rejected"
        req_row["error_code"] = "RATE_LIMITED"
        req_row["error_message"] = "Rate limit or daily quota exceeded."
        req_row["completed_at"] = now_iso
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        api_key["last_used_at"] = now_iso
        api_key["updated_at"] = now_iso
        _save("api_keys.json", keys)
        _save("tool_requests.json", reqs)
        return _err("RATE_LIMIT", "Rate limit exceeded.", request_id=req_id)

    req_row["status"] = "running"
    req_row["updated_at"] = now_iso
    _save("tool_requests.json", reqs)

    # Cursor handling: base64 json {"offset":int}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            cobj = json.loads(raw)
            if not isinstance(cobj, dict) or not isinstance(cobj.get("offset"), int) or cobj["offset"] < 0:
                raise ValueError("bad cursor")
            offset = cobj["offset"]
        except Exception:
            req_row["status"] = "failed"
            req_row["error_code"] = "VALIDATION_ERROR"
            req_row["error_message"] = "Invalid cursor."
            req_row["completed_at"] = now_iso
            req_row["updated_at"] = now_iso
            req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
            api_key["last_used_at"] = now_iso
            api_key["updated_at"] = now_iso
            _save("api_keys.json", keys)
            _save("tool_requests.json", reqs)
            return _err("VALIDATION_ERROR", "Invalid cursor.", request_id=req_id)

    eff_limit = limit if limit is not None else 50
    sfield = sort if sort is not None else "name"
    sorder = sort_order if sort_order is not None else "asc"

    q = query.lower()
    filtered = []
    for o in objs:
        if o.get("system_id") != system_id:
            continue
        if o.get("status") == "deleted":
            continue
        if q not in (o.get("name") or "").lower() and q not in (o.get("description") or "").lower():
            continue
        if object_types is not None and len(object_types) > 0 and o.get("object_type") not in object_types:
            continue
        if package_name is not None and (o.get("package_name") or "") != package_name:
            continue
        if is_standard is not None and bool(o.get("is_standard")) != is_standard:
            continue
        filtered.append(o)

    def _sort_key(o):
        v = o.get(sfield)
        if sfield == "updated_at":
            dt = _parse_dt(v)
            return dt or datetime.datetime(1970, 1, 1)
        if v is None:
            return ""
        return v

    reverse = (sorder == "desc")
    try:
        filtered.sort(key=_sort_key, reverse=reverse)
    except Exception:
        # Sorting error shouldn't crash; mark request failed (server side)
        req_row["status"] = "failed"
        req_row["error_code"] = "VALIDATION_ERROR"
        req_row["error_message"] = "Unable to sort results."
        req_row["completed_at"] = now_iso
        req_row["updated_at"] = now_iso
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        api_key["last_used_at"] = now_iso
        api_key["updated_at"] = now_iso
        _save("api_keys.json", keys)
        _save("tool_requests.json", reqs)
        return _err("VALIDATION_ERROR", "Unable to sort results.", request_id=req_id)

    total = len(filtered)
    page = filtered[offset: offset + eff_limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        cobj = {"offset": next_offset}
        next_cursor = base64.urlsafe_b64encode(json.dumps(cobj, separators=(",", ":")).encode("utf-8")).decode("utf-8")

    req_row["http_status"] = 200
    req_row["status"] = "succeeded"
    req_row["completed_at"] = now_iso
    req_row["updated_at"] = now_iso
    req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    api_key["last_used_at"] = now_iso
    api_key["updated_at"] = now_iso
    _save("api_keys.json", keys)
    _save("tool_requests.json", reqs)

    return {
        "system_id": system_id,
        "query": query,
        "items": page,
        "page": {
            "limit": eff_limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "total": total,
            "sort": sfield,
            "sort_order": sorder,
            "offset": offset,
        },
        "request_id": req_id,
    }

def ListToolRequests(system_id=None, status=None, tool_name=None, error_code=None, requested_after=None, requested_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, base64, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0303000" if __import__("os").path.isdir("./environment_mix/0303000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _decode_page_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or not tok:
            return None
        try:
            pad = "=" * ((4 - (len(tok) % 4)) % 4)
            raw = base64.urlsafe_b64decode((tok + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            last_ts = _parse_rfc3339(obj.get("last_requested_at"))
            last_id = obj.get("last_id")
            if last_ts is None or not isinstance(last_id, str) or not last_id:
                return None
            return {"last_requested_at": last_ts, "last_id": last_id}
        except Exception:
            return None

    def _encode_page_token(last_id, last_requested_at_dt):
        payload = {"last_id": last_id, "last_requested_at": _iso(last_requested_at_dt)}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    # ---- Validate inputs (relax system_id to accept datastore ids with 19+ chars) ----
    if system_id is not None:
        if not isinstance(system_id, str) or not system_id:
            return _err("VALIDATION_ERROR", "system_id must be a non-empty string.")
        if re.match(r"^adt_sys_[0-9A-Z]{19,32}$", system_id) is None:
            return _err("VALIDATION_ERROR", "system_id must match ^adt_sys_[0-9A-Z]{19}$")
    if status is not None:
        if status not in ("received", "running", "succeeded", "failed", "rejected"):
            return _err("VALIDATION_ERROR", "status is invalid.")
    if tool_name is not None and (not isinstance(tool_name, str) or len(tool_name) < 1):
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string.")
    if error_code is not None:
        if error_code not in ("KEY_REVOKED", "KEY_EXPIRED", "RATE_LIMITED", "SYSTEM_MISMATCH", "TABLE_READS_DISABLED", "SEARCH_DISABLED"):
            return _err("VALIDATION_ERROR", "error_code is invalid.")
    ra = _parse_rfc3339(requested_after) if requested_after is not None else None
    if requested_after is not None and ra is None:
        return _err("VALIDATION_ERROR", "requested_after must be RFC3339 date-time.")
    rb = _parse_rfc3339(requested_before) if requested_before is not None else None
    if requested_before is not None and rb is None:
        return _err("VALIDATION_ERROR", "requested_before must be RFC3339 date-time.")
    if ra and rb and ra > rb:
        return _err("VALIDATION_ERROR", "requested_after must be <= requested_before.")
    if page_size is not None:
        if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
            return _err("VALIDATION_ERROR", "page_size must be between 1 and 200.")
    else:
        page_size = 50

    cursor = _decode_page_token(page_token) if page_token is not None else None
    if page_token is not None and cursor is None:
        return _err("VALIDATION_ERROR", "page_token is invalid.")

    systems = _load("adt_systems.json")
    keys = _load("api_keys.json")
    requests = _load("tool_requests.json")

    # ---- Ambient auth: pick an active key (optionally matching system_id) ----
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _key_active(k):
        if not isinstance(k, dict):
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        return exp is None or exp > now

    sys_by_id = {s.get("id"): s for s in systems if isinstance(s, dict) and isinstance(s.get("id"), str)}
    api_key = None
    for k in keys:
        if not _key_active(k):
            continue
        sid = k.get("system_id")
        if system_id is not None and sid != system_id:
            continue
        srow = sys_by_id.get(sid)
        if not srow or srow.get("status") != "active":
            continue
        api_key = k
        break
    if api_key is None:
        # fall back to any active key on any active system (call has no explicit credential)
        for k in keys:
            if not _key_active(k):
                continue
            srow = sys_by_id.get(k.get("system_id"))
            if srow and srow.get("status") == "active":
                api_key = k
                break
    if api_key is None:
        return _err("UNAUTHORIZED", "Not authenticated.")

    # system_id must match authenticated key when provided
    if system_id is not None and api_key.get("system_id") != system_id:
        return _err("UNAUTHORIZED", "SYSTEM_MISMATCH")

    # ---- Log this call (reads included) ----
    # Create a tool_requests row for this call itself
    import secrets
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(19))

    req_id = _new_id("adt_req")
    call_req = {
        "id": req_id,
        "api_key_id": api_key.get("id"),
        "system_id": api_key.get("system_id"),
        "tool_name": "ListToolRequests",
        "request_params": {k: v for k, v in {
            "system_id": system_id,
            "status": status,
            "tool_name": tool_name,
            "error_code": error_code,
            "requested_after": requested_after,
            "requested_before": requested_before,
            "page_size": page_size,
            "page_token": page_token,
        }.items() if v is not None},
        "resolved_object_id": None,
        "http_status": None,
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "result_artifact_id": None,
        "status": "received",
        "requested_at": _iso(now),
        "completed_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    requests.append(call_req)
    _save("tool_requests.json", requests)

    # Transition received -> running
    call_req["status"] = "running"
    call_req["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("tool_requests.json", requests)

    # ---- Filter the stored audit rows that belong to this key + system ----
    rows = []
    for r in requests:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key.get("id"):
            continue
        if r.get("system_id") != api_key.get("system_id"):
            continue
        if system_id is not None and r.get("system_id") != system_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if error_code is not None and r.get("error_code") != error_code:
            continue
        rdt = _parse_rfc3339(r.get("requested_at"))
        if ra is not None and (rdt is None or rdt < ra):
            continue
        if rb is not None and (rdt is None or rdt > rb):
            continue
        rows.append(r)

    # ---- Sort requested_at desc (then id desc) ----
    def _sort_key(r):
        dt = _parse_rfc3339(r.get("requested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)

    # ---- Apply cursor pagination ----
    if cursor is not None:
        last_ts = cursor["last_requested_at"]
        last_id = cursor["last_id"]
        filtered = []
        for r in rows:
            dt = _parse_rfc3339(r.get("requested_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            rid = str(r.get("id") or "")
            # since we're sorted desc, we keep items strictly "after" the cursor in that order:
            if dt < last_ts:
                filtered.append(r)
            elif dt == last_ts and rid < last_id:
                filtered.append(r)
        rows = filtered

    page = rows[:page_size]
    has_more = len(rows) > page_size
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_page_token(str(last.get("id") or ""), _parse_rfc3339(last.get("requested_at")) or now)

    # ---- Complete call_req ----
    call_req["status"] = "succeeded"
    call_req["completed_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    call_req["updated_at"] = call_req["completed_at"]
    call_req["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", keys)
    _save("tool_requests.json", requests)

    return {
        "data": page,
        "meta": {
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def GetToolRequest(id, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0303000" if __import__("os").path.isdir("./environment_mix/0303000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    tool_name = "GetToolRequest"

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")
    id = id.strip()
    # Relax to accept actual store ids (adt_req_...) as seen in datastore digest.
    if re.match(r"^(tool_req|adt_req)_[0-9A-Z]{19,32}$", id) is None:
        return _err("VALIDATION_ERROR", "id format is invalid.")

    systems = _load("adt_systems.json")
    keys = _load("api_keys.json")
    requests = _load("tool_requests.json")

    if not isinstance(systems, list):
        systems = []
    if not isinstance(keys, list):
        keys = []
    if not isinstance(requests, list):
        requests = []

    # Ambient auth: require at least one active key in store (service-level auth context).
    # Prefer a key that can view the requested record (same api_key_id), else same system_id.
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    req = next((r for r in requests if isinstance(r, dict) and r.get("id") == id), None)
    if req is None:
        return _err("NOT_FOUND", "Tool request not found.")

    # Authenticate context: any active, non-expired key exists
    def _key_active(k):
        if not isinstance(k, dict):
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now:
            return False
        return True

    active_keys = [k for k in keys if _key_active(k)]
    if not active_keys:
        return _err("UNAUTHORIZED", "Caller is not authenticated.")

    # "FORBIDDEN when record does not belong to caller's API key/system"
    # With ambient auth and no credential param, we allow access if ANY active key matches api_key_id,
    # else if ANY active key matches system_id. Otherwise forbidden.
    if not any(k.get("id") == req.get("api_key_id") for k in active_keys):
        if not any(k.get("system_id") == req.get("system_id") for k in active_keys):
            return _err("UNAUTHORIZED", "Forbidden.")

    # Observability: record this call as a tool_requests row too.
    # Use an active key that matches the request system if possible.
    chosen = next((k for k in active_keys if k.get("system_id") == req.get("system_id")), active_keys[0])
    api_key_id = chosen.get("id")
    system_id = chosen.get("system_id")

    # Create a request log row for this read tool (no upstream call).
    import secrets
    alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    rid = "adt_req_" + "".join(secrets.choice(alphabet) for _ in range(19))
    ts = _iso(now)
    req_row = {
        "id": rid,
        "api_key_id": api_key_id,
        "system_id": system_id,
        "tool_name": tool_name,
        "request_params": {"id": id},
        "resolved_object_id": None,
        "http_status": None,
        "duration_ms": max(0, int((time.time() - t0) * 1000)),
        "error_code": None,
        "error_message": None,
        "result_artifact_id": None,
        "status": "succeeded",
        "requested_at": ts,
        "completed_at": ts,
        "created_at": ts,
        "updated_at": ts,
    }
    requests.append(req_row)
    _save("tool_requests.json", requests)

    return {"tool_request": req}

def ListAbapObjects(system_id, object_type=None, name_prefix=None, package_name=None, status=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, re, base64, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0303000" if __import__("os").path.isdir("./environment_mix/0303000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(19))

    def _encode_cursor(last_name, last_id):
        raw = json.dumps({"last_name": last_name, "last_id": last_id}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(tok):
        if not isinstance(tok, str) or not tok:
            return None
        pad = "=" * ((4 - (len(tok) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if not isinstance(obj.get("last_name"), str) or not isinstance(obj.get("last_id"), str):
                return None
            return obj
        except Exception:
            return None

    tool_name = "ListAbapObjects"

    if not isinstance(system_id, str) or not system_id:
        return _err("VALIDATION_ERROR", "system_id must be a non-empty string.")
    if re.match(r"^adt_sys_[0-9A-Z]{19,32}$", system_id) is None:
        return _err("VALIDATION_ERROR", "Invalid system_id format.")
    valid_types = {"PROGRAM","CLASS","INTERFACE","FUNCTION_GROUP","FUNCTION_MODULE","INCLUDE","PACKAGE","DDIC_TABLE","DDIC_STRUCTURE","TYPEINFO"}
    if object_type is not None and object_type not in valid_types:
        return _err("VALIDATION_ERROR", "Invalid object_type.")
    if name_prefix is not None and (not isinstance(name_prefix, str) or len(name_prefix) < 1):
        return _err("VALIDATION_ERROR", "name_prefix must be a non-empty string.")
    if package_name is not None and (not isinstance(package_name, str) or len(package_name) < 1):
        return _err("VALIDATION_ERROR", "package_name must be a non-empty string.")
    if status is not None and status not in {"known","stale","deleted"}:
        return _err("VALIDATION_ERROR", "Invalid status.")
    if page_size is not None:
        if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
            return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")
    if page_token is not None and (not isinstance(page_token, str) or len(page_token) < 1):
        return _err("VALIDATION_ERROR", "page_token must be a non-empty string.")

    page_size = page_size or 50

    systems = _load("adt_systems.json")
    keys = _load("api_keys.json")
    objects = _load("abap_objects.json")
    requests = _load("tool_requests.json")

    sys_row = next((s for s in systems if isinstance(s, dict) and s.get("id") == system_id), None)
    if not sys_row:
        return _err("NOT_FOUND", "ADT system not found.")

    # ambient auth: find an active key for this system (must match system for access)
    def _key_is_active_for_system(k):
        if not isinstance(k, dict):
            return False
        if k.get("system_id") != system_id:
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        return exp is None or exp > now

    api_key = next((k for k in keys if _key_is_active_for_system(k)), None)
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key context available for this system.")

    # log request (read included)
    req_id = _new_id("adt_req")
    ts0 = _iso(now)
    req_row = {
        "id": req_id,
        "api_key_id": api_key["id"],
        "system_id": system_id,
        "tool_name": tool_name,
        "request_params": {"system_id": system_id, "object_type": object_type, "name_prefix": name_prefix, "package_name": package_name, "status": status, "page_size": page_size, "page_token": page_token},
        "resolved_object_id": None,
        "http_status": None,
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "result_artifact_id": None,
        "status": "received",
        "requested_at": ts0,
        "completed_at": None,
        "created_at": ts0,
        "updated_at": ts0,
    }
    requests.append(req_row)
    _save("tool_requests.json", requests)

    # rate limit/quota
    def _count_within(predicate):
        c = 0
        for r in requests:
            if not isinstance(r, dict) or r.get("api_key_id") != api_key["id"]:
                continue
            dt = _parse_dt(r.get("requested_at"))
            if dt is None:
                continue
            if predicate(dt):
                c += 1
        return c

    try:
        per_min = int(api_key.get("requests_per_minute_limit"))
    except Exception:
        per_min = 0
    try:
        per_day = int(api_key.get("requests_per_day_limit"))
    except Exception:
        per_day = 0

    min_count = _count_within(lambda dt: dt >= (now - datetime.timedelta(seconds=60)))
    day_count = _count_within(lambda dt: dt >= (now - datetime.timedelta(days=1)))

    def _reject(error_code, message, api_error_code):
        req_row["status"] = "rejected"
        req_row["error_code"] = error_code
        req_row["error_message"] = message
        req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        done = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_row["completed_at"] = done
        req_row["updated_at"] = done
        api_key["last_used_at"] = done
        api_key["updated_at"] = api_key.get("updated_at") or done
        _save("tool_requests.json", requests)
        _save("api_keys.json", keys)
        return _err(api_error_code, message)

    if per_min >= 0 and per_min != 0 and min_count > per_min:
        return _reject("RATE_LIMITED", "Rate limit exceeded (per-minute).", "RATE_LIMIT")
    if per_day >= 0 and per_day != 0 and day_count > per_day:
        return _reject("RATE_LIMITED", "Rate limit exceeded (per-day).", "QUOTA_EXCEEDED")

    req_row["status"] = "running"
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("tool_requests.json", requests)

    # filtering
    rows = [o for o in objects if isinstance(o, dict) and o.get("system_id") == system_id]
    if object_type is not None:
        rows = [o for o in rows if o.get("object_type") == object_type]
    if status is not None:
        rows = [o for o in rows if o.get("status") == status]
    if package_name is not None:
        rows = [o for o in rows if o.get("package_name") == package_name]
    if name_prefix is not None:
        pfx = name_prefix.lower()
        rows = [o for o in rows if isinstance(o.get("name"), str) and o["name"].lower().startswith(pfx)]

    # sort by name, then id
    rows.sort(key=lambda r: ((r.get("name") or ""), (r.get("id") or "")))

    # cursor paging
    cur = _decode_cursor(page_token) if page_token else None
    if cur:
        ln, lid = cur["last_name"], cur["last_id"]
        rows = [r for r in rows if ((r.get("name") or ""), (r.get("id") or "")) > (ln, lid)]

    page = rows[:page_size]
    has_more = len(rows) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor(last.get("name") or "", last.get("id") or "")

    req_row["status"] = "succeeded"
    req_row["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    done = _iso(datetime.datetime.now(datetime.timezone.utc))
    req_row["completed_at"] = done
    req_row["updated_at"] = done
    api_key["last_used_at"] = done
    api_key["updated_at"] = api_key.get("updated_at") or done

    _save("tool_requests.json", requests)
    _save("api_keys.json", keys)

    return {"request_id": req_row["id"], "system_id": system_id, "objects": page, "total": len([o for o in objects if isinstance(o, dict) and o.get("system_id") == system_id]), "has_more": has_more, "next_cursor": next_cursor}

