    if obj is None:
        return _err("NOT_FOUND", "ABAP object not found.")

    # Ambient auth: any active, non-expired key exists; must match object's system_id to be allowed.
    def _key_active(k):
        if not isinstance(k, dict):
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now:
            return False
        return True

    active_keys = [k for k in keys if _key_active(k)]
    if not active_keys:
        return _err("UNAUTHORIZED", "Caller is not authenticated.")

    obj_system_id = obj.get("system_id")
    if not isinstance(obj_system_id, str) or not obj_system_id:
        return _err("CONFLICT", "ABAP object has no system_id.")

    if not any(k.get("system_id") == obj_system_id for k in active_keys):
        return _err("UNAUTHORIZED", "Forbidden.")

    # Observability: record this call in tool_requests (read tool not listed in enum, so do not write there)
    # But schema enum for tool_requests.tool_name does not include GetAbapObject; avoid corrupting datastore.
    # Instead, update api_key last_used_at for one matching key to reflect usage dynamics.
    chosen = next((k for k in active_keys if k.get("system_id") == obj_system_id), active_keys[0])
    for i, k in enumerate(keys):
        if isinstance(k, dict) and k.get("id") == chosen.get("id"):
            k2 = dict(k)
            k2["last_used_at"] = _iso(now)
            k2["updated_at"] = _iso(now)
            keys[i] = k2
            _save("api_keys.json", keys)
            break

    # Return object as stored
    return {"abap_object": obj}

def ListAbapObjectArtifacts(object_id, artifact_kind=None, status=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, re, base64, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0303000" if __import__("os").path.isdir("./environment_mix/0303000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(19))

    def _decode_page_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or not tok:
            return None
        try:
            pad = "=" * ((4 - (len(tok) % 4)) % 4)
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            last_id = obj.get("last_id")
            if not isinstance(last_id, str) or not last_id:
                return None
            return {"last_id": last_id}
        except Exception:
            return None

    def _encode_page_token(last_id):
        raw = json.dumps({"last_id": last_id}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    tool_name = "ListAbapObjectArtifacts"

    # Validate
    if not isinstance(object_id, str) or re.match(r"^(abap_obj|adt_obj)_[0-9A-Z]{19,32}$", object_id) is None:
        return _err("VALIDATION_ERROR", "object_id is invalid.")
    if artifact_kind is not None and artifact_kind not in ("SOURCE", "DDIC_SCHEMA", "PACKAGE_DETAILS", "TYPEINFO", "TABLE_CONTENTS"):
        return _err("VALIDATION_ERROR", "artifact_kind is invalid.")
    if status is not None and status not in ("current", "superseded", "purged"):
        return _err("VALIDATION_ERROR", "status is invalid.")
    if page_size is not None:
        if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
            return _err("VALIDATION_ERROR", "page_size must be between 1 and 200.")
    else:
        page_size = 50
    cursor = _decode_page_token(page_token) if page_token is not None else None
    if page_token is not None and cursor is None:
        return _err("VALIDATION_ERROR", "page_token is invalid.")

    systems = _load("adt_systems.json")
    keys = _load("api_keys.json")
    objects = _load("abap_objects.json")
    artifacts = _load("abap_object_artifacts.json")
    requests = _load("tool_requests.json")

    sys_by_id = {s.get("id"): s for s in systems if isinstance(s, dict) and isinstance(s.get("id"), str)}

    def _key_is_active(k):
        if not isinstance(k, dict):
            return False
        if k.get("status") != "active":
            return False
        exp = _parse_dt(k.get("expires_at"))
        return exp is None or exp > now

    api_key = None
    for k in keys:
        if not _key_is_active(k):
            continue
        srow = sys_by_id.get(k.get("system_id"))
        if srow and srow.get("status") == "active":
            api_key = k
            break
    if api_key is None:
        return _err("UNAUTHORIZED", "Not authenticated.")

    # Log this call itself
    call_req = {
        "id": _new_id("adt_req"),
        "api_key_id": api_key.get("id"),
        "system_id": api_key.get("system_id"),
        "tool_name": tool_name,
        "request_params": {k: v for k, v in {
            "object_id": object_id,
            "artifact_kind": artifact_kind,
            "status": status,
            "page_size": page_size,
            "page_token": page_token,
        }.items() if v is not None},
        "resolved_object_id": object_id,
        "http_status": None,
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "result_artifact_id": None,
        "status": "received",
        "requested_at": _iso(now),
        "completed_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    requests.append(call_req)
    _save("tool_requests.json", requests)

    call_req["status"] = "running"
    call_req["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("tool_requests.json", requests)

    obj = next((o for o in objects if isinstance(o, dict) and o.get("id") == object_id), None)
    if obj is None:
        call_req["status"] = "failed"
        call_req["error_code"] = "NOT_FOUND"
        call_req["error_message"] = "ABAP object not found"
        call_req["completed_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        call_req["updated_at"] = call_req["completed_at"]
        call_req["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        _save("tool_requests.json", requests)
        return _err("NOT_FOUND", "ABAP object not found")

    if obj.get("system_id") != api_key.get("system_id"):
        call_req["status"] = "rejected"
        call_req["error_code"] = "FORBIDDEN"
        call_req["error_message"] = "Object belongs to a different system."
        call_req["completed_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        call_req["updated_at"] = call_req["completed_at"]
        call_req["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        _save("tool_requests.json", requests)
        return _err("UNAUTHORIZED", "FORBIDDEN")

    rows = []
    for a in artifacts:
        if not isinstance(a, dict):
            continue
        if a.get("object_id") != object_id:
            continue
        if artifact_kind is not None and a.get("artifact_kind") != artifact_kind:
            continue
        if status is not None and a.get("status") != status:
            continue
        rows.append(a)

    # sort retrieved_at desc then id desc
    def _sort_key(a):
        dt = _parse_dt(a.get("retrieved_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(a.get("id") or ""))
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)

    if cursor is not None:
        last_id = cursor["last_id"]
        # since ids are unique and we sort desc, we can paginate by id position
        # find first index strictly after cursor id
        idx = None
        for i, a in enumerate(rows):
            if str(a.get("id") or "") == last_id:
                idx = i + 1
                break
        rows = rows[idx:] if idx is not None else rows

    page = rows[:page_size]
    has_more = len(rows) > page_size
    next_cursor = _encode_page_token(str(page[-1].get("id") or "")) if has_more and page else None

    call_req["status"] = "succeeded"
    call_req["completed_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    call_req["updated_at"] = call_req["completed_at"]
    call_req["duration_ms"] = max(0, int((time.time() - t0) * 1000))
    api_key["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    api_key["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("api_keys.json", keys)
    _save("tool_requests.json", requests)

    return {
        "data": page,
        "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}
    }

def GetCallerIdentity(include_quota=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0303000" if __import__("os").path.isdir("./environment_mix/0303000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        import secrets
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(secrets.choice(alphabet) for _ in range(19))

    start = time.time()
    requested_at = _now()
    tool_name = "GetCallerIdentity"

    if include_quota is None:
        include_quota = False
    if not isinstance(include_quota, bool):
        return _err("VALIDATION_ERROR", "Invalid include_quota.", field="include_quota")

    api_keys = _load("api_keys.json")
    systems = _load("adt_systems.json")
    requests = _load("tool_requests.json")

    # Ambient auth: choose any active + unexpired key with an active system
    now = _now()
    chosen_key = None
    chosen_system = None
    for k in api_keys:
        if k.get("status") != "active":
            continue
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now:
            continue
        sysrow = next((s for s in systems if s.get("id") == k.get("system_id") and s.get("status") == "active"), None)
        if not sysrow:
            continue
        chosen_key = k
        chosen_system = sysrow
        break

    if chosen_key is None:
        return _err("UNAUTHORIZED", "No authenticated caller.")

    # Create tool_requests row status=received BEFORE any further work
    req_id = _gen_id("req")
    safe_params = {"include_quota": include_quota}
    req_row = {
        "id": req_id,
        "api_key_id": chosen_key.get("id"),
        "system_id": chosen_system.get("id"),
        "tool_name": tool_name,
        "request_params": safe_params,
        "resolved_object_id": None,
        "http_status": None,
        "duration_ms": 0,
        "error_code": None,
        "error_message": None,
        "result_artifact_id": None,
        "status": "received",
        "requested_at": _iso(requested_at),
        "completed_at": None,
        "created_at": _iso(requested_at),
        "updated_at": _iso(requested_at),
    }
    requests.append(req_row)
    _save("tool_requests.json", requests)

    def _finalize(req_status, error_code=None, error_message=None):
        nonlocal requests
        requests = _load("tool_requests.json")
        r = next((x for x in requests if x.get("id") == req_id), None)
        if r is None:
            r = req_row
            requests.append(r)

        transitions = {
            "received": {"running", "rejected", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
            "rejected": set(),
        }
        cur = r.get("status")
        if req_status not in transitions.get(cur, set()):
            if "failed" in transitions.get(cur, set()):
                req_status = "failed"
                error_code = error_code or "INVALID_TRANSITION"
                error_message = error_message or "Illegal request lifecycle transition."
            else:
                req_status = cur

        if req_status == "running":
            r["status"] = "running"
            r["updated_at"] = _iso(_now())
            _save("tool_requests.json", requests)
            return

        completed = _now()
        r["status"] = req_status
        r["error_code"] = error_code
        r["error_message"] = error_message
        r["completed_at"] = _iso(completed)
        r["updated_at"] = _iso(completed)
        r["duration_ms"] = max(0, int((time.time() - start) * 1000))
        _save("tool_requests.json", requests)

        # update api_key last_used_at
        api_keys2 = _load("api_keys.json")
        k2 = next((x for x in api_keys2 if x.get("id") == chosen_key.get("id")), None)
        if k2 is not None:
            k2["last_used_at"] = _iso(completed)
            k2["updated_at"] = _iso(completed)
            _save("api_keys.json", api_keys2)

    # If revoked/expired, tool says FORBIDDEN
    if chosen_key.get("status") != "active":
        _finalize("rejected", error_code="KEY_REVOKED", error_message="API key is not active.")
        return _err("FORBIDDEN", "API key revoked.")
    exp = _parse_dt(chosen_key.get("expires_at"))
    if exp is not None and exp <= now:
        _finalize("rejected", error_code="KEY_EXPIRED", error_message="API key is expired.")
        return _err("FORBIDDEN", "API key expired.")

    # Rate limit / quota enforcement still applies
    per_min = chosen_key.get("requests_per_minute_limit", 0)
    per_day = chosen_key.get("requests_per_day_limit", 0)
    if not isinstance(per_min, int) or per_min < 0:
        per_min = 0
    if not isinstance(per_day, int) or per_day < 0:
        per_day = 0

    reqs_for_key = [r for r in requests if r.get("api_key_id") == chosen_key.get("id") and isinstance(r.get("requested_at"), str)]
    one_min_ago = requested_at - datetime.timedelta(seconds=60)
    day_start = requested_at.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

    min_count = 0
    day_count = 0
    for r in reqs_for_key:
        t = _parse_dt(r.get("requested_at"))
        if t is None:
            continue
        if t >= one_min_ago and t <= requested_at:
            min_count += 1
        if t >= day_start and t <= requested_at:
            day_count += 1

    if per_min == 0 or per_day == 0:
        _finalize("rejected", error_code="RATE_LIMITED", error_message="Rate limit exceeded.")
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=per_min, limit_per_day=per_day)

    if min_count > per_min or day_count > per_day:
        _finalize("rejected", error_code="RATE_LIMITED", error_message="Rate limit exceeded.")
        code = "RATE_LIMIT" if min_count > per_min else "QUOTA_EXCEEDED"
        return _err(code, "Rate limit exceeded." if code == "RATE_LIMIT" else "Daily quota exceeded.",
                    limit_per_minute=per_min, limit_per_day=per_day, used_last_minute=min_count, used_today=day_count)

    # Execute
    _finalize("running")

    # Effective feature flags combine system+key policy
    effective = {
        "system_status": chosen_system.get("status"),
        "verify_tls": bool(chosen_system.get("verify_tls")),
        "default_language": chosen_system.get("default_language"),
        "default_abap_language_version": chosen_system.get("default_abap_language_version"),
        "allow_quick_search": bool(chosen_system.get("allow_quick_search")),
        "allow_table_reads": bool(chosen_system.get("allow_table_reads")) and bool(chosen_key.get("allow_table_reads")),
        "table_read_row_limit": chosen_system.get("table_read_row_limit"),
    }

    identity = {
        "api_key": {
            "id": chosen_key.get("id"),
            "name": chosen_key.get("name"),
            "key_prefix": chosen_key.get("key_prefix"),
            "status": chosen_key.get("status"),
            "expires_at": chosen_key.get("expires_at"),
            "system_id": chosen_key.get("system_id"),
            "allowed_tools": chosen_key.get("allowed_tools"),
            "requests_per_minute_limit": chosen_key.get("requests_per_minute_limit"),
            "requests_per_day_limit": chosen_key.get("requests_per_day_limit"),
            "last_used_at": chosen_key.get("last_used_at"),
            "created_at": chosen_key.get("created_at"),
            "updated_at": chosen_key.get("updated_at"),
        },
        "system": {
            "id": chosen_system.get("id"),
            "name": chosen_system.get("name"),
            "base_url": chosen_system.get("base_url"),
            "client": chosen_system.get("client"),
            "status": chosen_system.get("status"),
        },
        "effective_features": effective,
    }

    if include_quota:
        minute_window_start = one_min_ago
        minute_window_reset = requested_at + datetime.timedelta(seconds=60)
        day_window_reset = (day_start + datetime.timedelta(days=1))

        identity["quota"] = {
            "used_last_60s": min_count,
            "used_today": day_count,
            "limits": {"per_minute": per_min, "per_day": per_day},
            "windows": {
                "minute_window_start": _iso(minute_window_start),
                "minute_window_end": _iso(requested_at),
                "minute_resets_at": _iso(minute_window_reset),
                "day_window_start": _iso(day_start),
                "day_window_end": _iso(requested_at),
                "day_resets_at": _iso(day_window_reset),
            },
        }

    _finalize("succeeded")
    return identity
